using GraphApi.Models.FNZ.Cuotas;namespace GraphApi.Services.FNZ.Cuotas{    /// <summary>    /// Define las operaciones de negocio y persistencia para Cuotas.    /// </summary>    public interface ICuotasService    {        /// <summary>        /// Obtiene la lista de Cuotas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadCuotas>> GetCuotas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Cuotas con filtros opcionales.        /// </summary>        /// <param name="cuotaID">Filtro opcional para CuotaID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="casaID">Filtro opcional para CasaID.</param>        /// <param name="monto">Filtro opcional para Monto.</param>        /// <param name="periodoInicio">Filtro opcional para PeriodoInicio.</param>        /// <param name="periodoFin">Filtro opcional para PeriodoFin.</param>        /// <param name="fechaVencimiento">Filtro opcional para FechaVencimiento.</param>        /// <param name="pagado">Filtro opcional para Pagado.</param>        /// <param name="fechaPago">Filtro opcional para FechaPago.</param>        /// <param name="metodoPago">Filtro opcional para MetodoPago.</param>        /// <param name="referenciaPago">Filtro opcional para ReferenciaPago.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetCuotasDynamic(            int? cuotaID,            int? usuarioID,            int? casaID,            decimal? monto,            DateTime? periodoInicio,            DateTime? periodoFin,            DateTime? fechaVencimiento,            bool? pagado,            DateTime? fechaPago,            string? metodoPago,            string? referenciaPago,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Cuota.        /// </summary>        /// <param name="objInput">Datos para crear el Cuota.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadCuotas> CreateCuotas(            clCreateCuotas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Cuota.        /// </summary>        /// <param name="objInput">Datos para actualizar el Cuota, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadCuotas?> UpdateCuotas(            clUpdateCuotas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Cuota por su ID.        /// </summary>        /// <param name="nCuotasID">ID del Cuota a eliminar.</param>        Task<bool> DeleteCuotas(int nCuotasID);    }}